\documentclass{article}
\usepackage[paperwidth=841mm,paperheight=1189mm,margin=0mm]{geometry}
\usepackage{tcolorbox}
\tcbuselibrary{poster,skins,fitting}
\usepackage{graphicx}
\usepackage{amsmath,amssymb}
\usepackage{enumitem}
\usepackage[table]{xcolor}
\usepackage{lmodern}
\usepackage[T1]{fontenc}
\usepackage{microtype}
\pagestyle{empty}

% ── Color Palette: Deep Navy + Teal + Amber accent ──
\definecolor{primary}{HTML}{0B2545}      % deep navy
\definecolor{secondary}{HTML}{1A6B8A}    % muted teal
\definecolor{accent}{HTML}{C8720C}       % amber/warm accent (risk callouts)
\definecolor{bgposter}{HTML}{F4F7FA}     % cool off-white poster background
\definecolor{textdark}{HTML}{0D1F2D}
\definecolor{textgray}{HTML}{3D5166}

% Card background tints
\definecolor{navybg}{HTML}{EBF1F8}
\definecolor{tealbg}{HTML}{E6F3F7}
\definecolor{amberbg}{HTML}{FDF4E7}
\definecolor{darkerbg}{HTML}{E2EAF2}

% Card title bar tints
\definecolor{navytitlebg}{HTML}{D3DFF0}
\definecolor{tealtitlebg}{HTML}{CCE8F0}
\definecolor{ambertitlebg}{HTML}{FAE8CC}
\definecolor{darktitlebg}{HTML}{C8D8EC}

% Stat highlight
\definecolor{stathighlight}{HTML}{FEF3E2}
\definecolor{riskred}{HTML}{FDECEA}

\pagecolor{bgposter}
\color{textdark}

% ── List styling ──
\setlist[itemize]{leftmargin=22pt, itemsep=8pt, parsep=0pt, topsep=4pt,
  label={\color{secondary}$\blacktriangleright$}}
\setlist[enumerate]{leftmargin=26pt, itemsep=8pt, parsep=0pt, topsep=4pt,
  label={\color{primary}\bfseries\arabic*.}}

% ── Figure macro ──
\newcommand{\posterfig}[3]{%
  \centering\includegraphics[width=#1\linewidth]{#2}\\[3mm]
  {\fontsize{26}{32}\selectfont\color{textgray}\textit{#3}}\vspace{2mm}%
}

% ── Sub-header macro ──
\newcommand{\subhead}[1]{%
  {\fontsize{32}{40}\selectfont\bfseries\color{primary} #1}\par\vspace{4pt}%
}

% ── Card styles ──
\tcbset{
  navycard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=navybg,
    borderline west={6pt}{0pt}{primary},
    left=18pt, right=16pt, top=6pt, bottom=6pt,
    fonttitle=\fontsize{38}{46}\selectfont\bfseries\color{primary},
    coltitle=primary, colbacktitle=navytitlebg,
    toptitle=6pt, bottomtitle=6pt,
    titlerule=2pt, titlerule style={primary!40},
    valign=top, drop shadow={opacity=0.15},
  },
  tealcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=tealbg,
    borderline west={6pt}{0pt}{secondary},
    left=18pt, right=16pt, top=6pt, bottom=6pt,
    fonttitle=\fontsize{38}{46}\selectfont\bfseries\color{secondary},
    coltitle=secondary, colbacktitle=tealtitlebg,
    toptitle=6pt, bottomtitle=6pt,
    titlerule=2pt, titlerule style={secondary!40},
    valign=top, drop shadow={opacity=0.15},
  },
  ambercard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=amberbg,
    borderline west={6pt}{0pt}{accent},
    left=18pt, right=16pt, top=6pt, bottom=6pt,
    fonttitle=\fontsize{38}{46}\selectfont\bfseries\color{accent},
    coltitle=accent, colbacktitle=ambertitlebg,
    toptitle=6pt, bottomtitle=6pt,
    titlerule=2pt, titlerule style={accent!50},
    valign=top, drop shadow={opacity=0.15},
  },
  highlightcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=primary!14!white,
    borderline west={7pt}{0pt}{primary},
    left=18pt, right=16pt, top=6pt, bottom=6pt,
    fonttitle=\fontsize{38}{46}\selectfont\bfseries\color{white},
    coltitle=white, colbacktitle=primary,
    toptitle=6pt, bottomtitle=6pt,
    valign=top, drop shadow={opacity=0.20},
  },
}

\begin{document}
\begin{tcbposter}[
  coverage={spread},
  poster={columns=3, rows=20, spacing=0mm},
]

%% ══════════════════════════════════════════════════════════
%% TITLE BAR
%% ══════════════════════════════════════════════════════════
\posterbox[
  enhanced, colback=primary, colframe=primary,
  arc=0pt, boxrule=0pt,
  left=44pt, right=44pt, top=16pt, bottom=14pt,
  halign=center, valign=center,
  drop shadow={opacity=0.28}
]{name=title, column=1, span=3, between=top and row4}{
  {\fontsize{74}{88}\selectfont\bfseries\color{white}%
    Large Language Models in Medicine}\\[10pt]
  {\fontsize{40}{50}\selectfont\color{white!85}%
    Opportunities, Risks, and the Path Forward}\\[10pt]
  {\fontsize{30}{38}\selectfont\color{white!65}%
    Comprehensive Review \textbf{·} Medical AI \& Digital Health Conference 2024 \textbf{·} \textit{Nature Medicine}, July 2023}
}

%% ══════════════════════════════════════════════════════════
%% STATS BANNER  (row4 – row7)
%% ══════════════════════════════════════════════════════════
\posterbox[
  enhanced, colback=primary!10!bgposter,
  boxrule=0pt, arc=0pt,
  left=10pt, right=10pt, top=10pt, bottom=10pt,
  valign=center,
  borderline south={3pt}{0pt}{primary!30},
  borderline north={3pt}{0pt}{primary!30},
]{name=stats, column=1, span=3, between=row4 and row7}{
  \centering
  \begin{minipage}[c]{0.235\linewidth}\centering
    \fcolorbox{primary!35}{navybg}{\parbox{0.88\linewidth}{%
      \centering\vspace{8pt}%
      {\fontsize{62}{74}\selectfont\bfseries\color{primary} $>$90\%}\\[4pt]
      {\fontsize{27}{33}\selectfont\bfseries\color{textdark} GPT-4 USMLE Score}\\[3pt]
      {\fontsize{24}{30}\selectfont\color{textgray} Exceeds physician passing threshold}\vspace{8pt}%
    }}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.235\linewidth}\centering
    \fcolorbox{secondary!35}{tealbg}{\parbox{0.88\linewidth}{%
      \centering\vspace{8pt}%
      {\fontsize{62}{74}\selectfont\bfseries\color{secondary} 500+}\\[4pt]
      {\fontsize{27}{33}\selectfont\bfseries\color{textdark} PubMed Articles (2023)}\\[3pt]
      {\fontsize{24}{30}\selectfont\color{textgray} Peer-reviewed publications in one year}\vspace{8pt}%
    }}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.235\linewidth}\centering
    \fcolorbox{accent!50}{stathighlight}{\parbox{0.88\linewidth}{%
      \centering\vspace{8pt}%
      {\fontsize{62}{74}\selectfont\bfseries\color{accent} 30\%}\\[4pt]
      {\fontsize{27}{33}\selectfont\bfseries\color{textdark} Hallucination Rate}\\[3pt]
      {\fontsize{24}{30}\selectfont\color{textgray} In medical QA tasks --- fabricated answers}\vspace{8pt}%
    }}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.235\linewidth}\centering
    \fcolorbox{primary!25}{darkerbg}{\parbox{0.88\linewidth}{%
      \centering\vspace{8pt}%
      {\fontsize{62}{74}\selectfont\bfseries\color{primary} \$10.5B}\\[4pt]
      {\fontsize{27}{33}\selectfont\bfseries\color{textdark} Health LLM Market}\\[3pt]
      {\fontsize{24}{30}\selectfont\color{textgray} Projected global value by 2030}\vspace{8pt}%
    }}
  \end{minipage}
}

%% ══════════════════════════════════════════════════════════
%% COLUMN 1 — OVERVIEW + BENCHMARKS
%% ══════════════════════════════════════════════════════════

%% --- Overview / Background  (row7 – row12) ---
\posterbox[navycard, title={What Are LLMs \& Why Medicine?}
]{name=overview, column=1, between=row7 and row12}{
  \fontsize{33}{43}\selectfont
  Foundation models trained on massive text corpora --- now rapidly entering clinical practice.

  \vspace{10pt}
  \begin{itemize}[itemsep=10pt]
    \item GPT-4, Med-PaLM 2, LLaMA leading healthcare adoption
    \item Understand and generate \textbf{complex medical text}
    \item 500+ peer-reviewed papers in 2023 alone
  \end{itemize}

  \vspace{10pt}
  \colorbox{primary!18}{\parbox{0.94\linewidth}{%
    \vspace{6pt}\fontsize{30}{38}\selectfont\color{primary}%
    \textbf{Core Capability:} Encode biomedical knowledge at near-expert level --- without explicit clinical training\vspace{6pt}%
  }}
}

%% --- Benchmark Performance  (row12 – row18) ---
\posterbox[tealcard, title={Benchmark Performance}
]{name=benchmarks, column=1, between=row12 and row18}{
  \fontsize{33}{43}\selectfont

  \renewcommand{\arraystretch}{1.65}
  \begin{tabular}{@{}p{0.42\linewidth} p{0.22\linewidth} p{0.27\linewidth}@{}}
    \rowcolor{secondary!15}
    \fontsize{28}{34}\selectfont\bfseries Model &
    \fontsize{28}{34}\selectfont\bfseries Score &
    \fontsize{28}{34}\selectfont\bfseries Benchmark \\
    {\fontsize{28}{34}\selectfont GPT-4} &
    {\fontsize{28}{34}\selectfont \textbf{>90\%}} &
    {\fontsize{28}{34}\selectfont USMLE} \\
    \rowcolor{secondary!8}
    {\fontsize{28}{34}\selectfont Med-PaLM 2} &
    {\fontsize{28}{34}\selectfont \textbf{86.5\%}} &
    {\fontsize{28}{34}\selectfont MedQA} \\
    {\fontsize{28}{34}\selectfont GPT-3.5} &
    {\fontsize{28}{34}\selectfont $\sim$60\%} &
    {\fontsize{28}{34}\selectfont USMLE} \\
    \rowcolor{secondary!8}
    {\fontsize{28}{34}\selectfont Pass threshold} &
    {\fontsize{28}{34}\selectfont $\approx$60\%} &
    {\fontsize{28}{34}\selectfont (human)} \\
  \end{tabular}

  \vspace{10pt}
  \colorbox{secondary!20}{\parbox{0.94\linewidth}{%
    \vspace{6pt}\fontsize{30}{38}\selectfont%
    \textbf{Gap:} Benchmark $\neq$ clinical safety --- real-world validation still lacking\vspace{6pt}%
  }}

  \vspace{8pt}
  \begin{itemize}[itemsep=8pt]
    \item Complex \textbf{clinical reasoning} remains less characterized
    \item MCQ formats may overstate true diagnostic ability
  \end{itemize}
}

%% --- References  (row18 – bottom) ---
\posterbox[navycard, title={References}
]{name=references, column=1, between=row18 and bottom}{
  \fontsize{27}{36}\selectfont
  \begin{itemize}[label={}, leftmargin=0pt, itemsep=6pt]
    \item Singhal et al.\ (2023). Large language models encode clinical knowledge. \textit{Nature}.
    \item Nori et al.\ (2023). Capabilities of GPT-4 on medical challenge problems. \textit{arXiv}.
    \item Thirunavukarasu et al.\ (2023). LLMs in medicine. \textit{Nature Medicine}.
    \item Omiye et al.\ (2023). LLMs in medical education. \textit{npj Digital Medicine}.
  \end{itemize}
}

%% ══════════════════════════════════════════════════════════
%% COLUMN 2 — APPLICATIONS + RISKS
%% ══════════════════════════════════════════════════════════

%% --- Clinical Applications  (row7 – row13) ---
\posterbox[tealcard, title={Key Clinical \& Research Applications}
]{name=applications, column=2, between=row7 and row13}{
  \fontsize{33}{43}\selectfont

  \renewcommand{\arraystretch}{1.6}
  \begin{tabular}{@{}p{0.44\linewidth} p{0.50\linewidth}@{}}
    \rowcolor{secondary!15}
    \fontsize{28}{34}\selectfont\bfseries Domain &
    \fontsize{28}{34}\selectfont\bfseries Maturity \\
    {\fontsize{28}{34}\selectfont Clinical Documentation} &
    {\fontsize{28}{34}\selectfont\color{secondary}\bfseries Pilot deployments} \\
    \rowcolor{secondary!8}
    {\fontsize{28}{34}\selectfont Patient Communication} &
    {\fontsize{28}{34}\selectfont\color{secondary}\bfseries Early adoption} \\
    {\fontsize{28}{34}\selectfont Medical Education} &
    {\fontsize{28}{34}\selectfont\color{secondary}\bfseries Active use} \\
    \rowcolor{secondary!8}
    {\fontsize{28}{34}\selectfont Diagnostic Support} &
    {\fontsize{28}{34}\selectfont\color{textgray} Research stage} \\
    {\fontsize{28}{34}\selectfont Biomedical Research} &
    {\fontsize{28}{34}\selectfont\color{textgray} Emerging} \\
  \end{tabular}

  \vspace{10pt}
  \begin{itemize}[itemsep=10pt]
    \item Fastest adoption: \textbf{EHR-integrated note generation}
    \item LLM tutors now used in medical exam preparation
    \item Automated discharge summaries $\to$ reduced clinician burden
  \end{itemize}

  \vspace{8pt}
  \colorbox{secondary!20}{\parbox{0.94\linewidth}{%
    \vspace{6pt}\fontsize{30}{38}\selectfont%
    \textbf{Key:} Real-world adoption fastest where human review remains in-loop\vspace{6pt}%
  }}
}

%% --- Risks, Limitations, and Ethical Concerns  (row13 – row20) ---
\posterbox[ambercard, title={Risks, Limitations \& Ethical Concerns}
]{name=risks, column=2, between=row13 and bottom}{
  \fontsize{33}{43}\selectfont

  \colorbox{accent!22}{\parbox{0.94\linewidth}{%
    \vspace{5pt}\fontsize{30}{38}\selectfont\color{accent}%
    \textbf{\large Hallucinations:} Up to \textbf{30\%} of medical QA outputs contain fabricated references or inaccurate clinical facts\vspace{5pt}%
  }}

  \vspace{10pt}
  \begin{enumerate}[itemsep=12pt]
    \item \textbf{Hallucinations} --- plausible but wrong information; fake citations common
    \item \textbf{Bias \& Equity} --- training data biases may amplify care disparities
    \item \textbf{Privacy} --- prompts with patient data risk HIPAA/GDPR violations
    \item \textbf{Lack of Clinical Validation} --- benchmarks $\neq$ prospective trials
    \item \textbf{Over-reliance Risk} --- automation bias; clinicians accept outputs uncritically
  \end{enumerate}

  \vspace{10pt}
  \colorbox{accent!18}{\parbox{0.94\linewidth}{%
    \vspace{5pt}\fontsize{30}{38}\selectfont%
    \textbf{Core tension:} GPT-4 scores $>$90\% on USMLE \textbf{yet} may hallucinate on the next query\vspace{5pt}%
  }}

  \vspace{8pt}
  \colorbox{primary!15}{\parbox{0.94\linewidth}{%
    \vspace{5pt}\fontsize{30}{38}\selectfont%
    \textbf{No LLM has passed prospective clinical trial evaluation.}\vspace{5pt}%
  }}
}

%% ══════════════════════════════════════════════════════════
%% COLUMN 3 — FRAMEWORK + TAKEAWAYS
%% ══════════════════════════════════════════════════════════

%% --- Responsible Deployment Framework  (row7 – row16) ---
\posterbox[navycard, title={Framework for Responsible Deployment}
]{name=framework, column=3, between=row7 and row16}{
  \fontsize{33}{43}\selectfont
  Multi-stakeholder framework for safe clinical integration:

  \vspace{10pt}
  \colorbox{primary!20}{\parbox{0.94\linewidth}{%
    \vspace{6pt}\fontsize{31}{40}\selectfont%
    \textbf{1. Rigorous Prospective Evaluation}\\
    Test in diverse clinical settings \textit{before} deployment\vspace{6pt}%
  }}

  \vspace{8pt}
  \colorbox{secondary!20}{\parbox{0.94\linewidth}{%
    \vspace{6pt}\fontsize{31}{40}\selectfont%
    \textbf{2. Human-in-the-Loop Design}\\
    Clinician oversight of \textit{all} LLM-generated outputs\vspace{6pt}%
  }}

  \vspace{8pt}
  \colorbox{primary!14}{\parbox{0.94\linewidth}{%
    \vspace{6pt}\fontsize{31}{40}\selectfont%
    \textbf{3. Transparent Reporting}\\
    Disclose limitations, training data, known failure modes\vspace{6pt}%
  }}

  \vspace{8pt}
  \colorbox{accent!18}{\parbox{0.94\linewidth}{%
    \vspace{6pt}\fontsize{31}{40}\selectfont%
    \textbf{4. Equity Audits}\\
    Assess differential performance across patient populations\vspace{6pt}%
  }}

  \vspace{8pt}
  \colorbox{secondary!15}{\parbox{0.94\linewidth}{%
    \vspace{6pt}\fontsize{31}{40}\selectfont%
    \textbf{5. Regulatory Alignment}\\
    Comply with FDA, EMA \& WHO AI-device guidance\vspace{6pt}%
  }}

  \vspace{10pt}
  \begin{itemize}[itemsep=8pt]
    \item Evidence $\to$ equity $\to$ governance: required in sequence
    \item No deployment without prospective safety data
  \end{itemize}
}

%% --- Key Takeaways  (row16 – bottom) ---
\posterbox[highlightcard, title={Key Takeaways}
]{name=takeaways, column=3, between=row16 and bottom}{
  \fontsize{33}{43}\selectfont

  \begin{enumerate}[itemsep=14pt]
    \item LLMs demonstrate \textbf{near-expert benchmark performance} in medicine --- but benchmarks are not clinical practice
    \item The \textbf{hallucination problem is real}: up to 30\% error rate is unacceptable in high-stakes care
    \item \textbf{Responsible deployment requires} prospective trials, human oversight, equity review, and regulatory compliance
  \end{enumerate}

  \vspace{14pt}
  \colorbox{accent!28}{\parbox{0.94\linewidth}{%
    \vspace{8pt}\centering\fontsize{32}{42}\selectfont\color{accent}%
    \textbf{``Transformative potential --- but only with evidence, equity, and robust governance.''}\vspace{8pt}%
  }}

  \vspace{10pt}
  {\fontsize{28}{36}\selectfont\color{textgray}%
    \textit{Thirunavukarasu et al., Nature Medicine 2023}}
}

\end{tcbposter}
\end{document}

